import { cn } from '@/lib/utils';

/**
 * Illustration — les 34 formes dessinées de la marque.
 *
 * Pourquoi les tracés sont inlinés et non chargés en <img> : ces formes servent
 * d'accent graphique posé sur des fonds variés, elles doivent donc prendre la
 * couleur du texte qui les entoure. Un <img> est opaque au CSS : on ne peut ni
 * le teinter, ni le passer en blanc sur le violet. L'inline règle les deux
 * problèmes d'un coup, et évite 34 requêtes réseau sur la page de référence.
 *
 * Les couleurs d'origine (#231F20, black) ont donc été remplacées par
 * currentColor. Les fichiers sources restent dans public/Assets/illustrations —
 * ils sont la source de vérité si une forme doit être redessinée.
 *
 * DEUX ACCÈS, et c'est un choix assumé, pas un doublon accidentel :
 *   - les 34 composants nommés (FormeEtoiles, FormeEtincelles, Forme1…) sont
 *     l'accès STATIQUE : un écran qui n'affiche qu'une étoile n'importe que
 *     cette fonction, et le bundler élague les 33 autres ;
 *   - `Illustration({ forme })` est l'accès DYNAMIQUE, quand la forme vient
 *     d'une donnée ou d'une boucle (page de référence du DS). Il consulte la
 *     table des 34 et embarque donc tout le jeu — environ 130 Ko de données de
 *     tracé, dont ~20 Ko pour la seule forme « etincelles ». À n'employer que
 *     lorsque la forme n'est pas connue à l'écriture.
 *
 * Le viewBox de chaque forme est recopié tel quel : ils ne sont PAS tous en
 * 0 0 64 64 (on trouve aussi 53, 65, 66, 67 de large, et un 33x51). Uniformiser
 * les viewBox écraserait les proportions. Comme la taille par défaut est carrée
 * (h-16 w-16, la cote Figma de 64px), les formes non carrées sont centrées par
 * le preserveAspectRatio par défaut plutôt qu'étirées.
 *
 * Aucun de ces fichiers ne contient de <defs>, <clipPath>, <mask> ni d'attribut
 * id : les 34 tracés peuvent cohabiter sur une même page sans collision d'id.
 * Le générateur qui a produit ce fichier vérifiait ce point.
 *
 * Composants purs, sans état ni gestionnaire : pas de 'use client', ils peuvent
 * donc rester côté serveur quand ils sont utilisés depuis un composant serveur.
 */
export type NomForme =
  | 'deux-lignes-rondes'
  | 'deux-lignes-arrondies'
  | 'trois-points'
  | 'trois-lignes'
  | 'fleche'
  | 'double-ellipse'
  | 'courbe'
  | 'forme-horizontale-1'
  | 'forme-horizontale-2'
  | 'forme-horizontale-3'
  | 'forme-horizontale-4'
  | 'z-inverse'
  | 'trait'
  | 'lignes-en-rond'
  | 'arc-en-ciel'
  | 'forme-s'
  | 'forme-1'
  | 'forme-2'
  | 'forme-3'
  | 'forme-4'
  | 'forme-5'
  | 'forme-6'
  | 'forme-7'
  | 'forme-8'
  | 'forme-9'
  | 'forme-10'
  | 'forme-11'
  | 'ellipse-simple'
  | 'rond-simple'
  | 'rond-simple-2'
  | 'rond-simple-3'
  | 'etincelles'
  | 'etoiles'
  | 'forme-z';

/** Toutes les formes, dans l'ordre du Figma — sert la page de référence du DS. */
export const FORMES: readonly NomForme[] = [
  'deux-lignes-rondes',
  'deux-lignes-arrondies',
  'trois-points',
  'trois-lignes',
  'fleche',
  'double-ellipse',
  'courbe',
  'forme-horizontale-1',
  'forme-horizontale-2',
  'forme-horizontale-3',
  'forme-horizontale-4',
  'z-inverse',
  'trait',
  'lignes-en-rond',
  'arc-en-ciel',
  'forme-s',
  'forme-1',
  'forme-2',
  'forme-3',
  'forme-4',
  'forme-5',
  'forme-6',
  'forme-7',
  'forme-8',
  'forme-9',
  'forme-10',
  'forme-11',
  'ellipse-simple',
  'rond-simple',
  'rond-simple-2',
  'rond-simple-3',
  'etincelles',
  'etoiles',
  'forme-z',
] as const;

export type ProprietesForme = {
  className?: string;
  /**
   * Absent = la forme est décorative, elle est masquée aux lecteurs d'écran.
   * Présent = elle porte du sens : role="img" et <title>. Une forme abstraite
   * est décorative dans la quasi-totalité des cas.
   */
  titre?: string;
};

/** Enveloppe commune : c'est elle qui porte la cote, l'accessibilité et le cn(). */
function Cadre({
  boite,
  className,
  titre,
  children,
}: ProprietesForme & { boite: string; children: React.ReactNode }) {
  return (
    <svg
      viewBox={boite}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={cn('h-16 w-16 shrink-0', className)}
      role={titre ? 'img' : undefined}
      aria-hidden={titre ? undefined : true}
    >
      {titre ? <title>{titre}</title> : null}
      {children}
    </svg>
  );
}

