/**
 * Table des 34 formes. Elle n'est consultée que par `Illustration` : c'est ce
 * qui permet aux imports statiques des composants nommés de rester légers.
 */
const FORMES_PAR_NOM: Record<NomForme, (props: ProprietesForme) => React.JSX.Element> = {
  'deux-lignes-rondes': FormeDeuxLignesRondes,
  'deux-lignes-arrondies': FormeDeuxLignesArrondies,
  'trois-points': FormeTroisPoints,
  'trois-lignes': FormeTroisLignes,
  'fleche': FormeFleche,
  'double-ellipse': FormeDoubleEllipse,
  'courbe': FormeCourbe,
  'forme-horizontale-1': FormeHorizontale1,
  'forme-horizontale-2': FormeHorizontale2,
  'forme-horizontale-3': FormeHorizontale3,
  'forme-horizontale-4': FormeHorizontale4,
  'z-inverse': FormeZInverse,
  'trait': FormeTrait,
  'lignes-en-rond': FormeLignesEnRond,
  'arc-en-ciel': FormeArcEnCiel,
  'forme-s': FormeS,
  'forme-1': Forme1,
  'forme-2': Forme2,
  'forme-3': Forme3,
  'forme-4': Forme4,
  'forme-5': Forme5,
  'forme-6': Forme6,
  'forme-7': Forme7,
  'forme-8': Forme8,
  'forme-9': Forme9,
  'forme-10': Forme10,
  'forme-11': Forme11,
  'ellipse-simple': FormeEllipseSimple,
  'rond-simple': FormeRondSimple,
  'rond-simple-2': FormeRondSimple2,
  'rond-simple-3': FormeRondSimple3,
  'etincelles': FormeEtincelles,
  'etoiles': FormeEtoiles,
  'forme-z': FormeZ,
};

/**
 * Accès dynamique : à réserver aux cas où la forme n'est connue qu'à l'exécution.
 * Importer cette fonction embarque les 34 tracés (voir le commentaire d'en-tête).
 */
export function Illustration({
  forme,
  className,
  titre,
}: ProprietesForme & { forme: NomForme }) {
  const Forme = FORMES_PAR_NOM[forme];
  return <Forme className={className} titre={titre} />;
}
